 26→// Kiro implements the Agent interface for Amazon's Kiro CLI.
 27→type Kiro struct{}
 28→
 29→func (k *Kiro) Name() string               { return "kiro" }
 30→func (k *Kiro) Binary() string             { return "kiro-cli" }
 31→func (k *Kiro) EntireAgent() string        { return "kiro" }
 32→func (k *Kiro) PromptPattern() string      { return `!>` }
 33→func (k *Kiro) TimeoutMultiplier() float64 { return 1.5 }
 34→
 35→func (k *Kiro) IsTransientError(out Output, _ error) bool {
 36→	combined := out.Stdout + out.Stderr
 37→	for _, p := range []string{"overloaded", "rate limit", "503", "529", "throttl"} {
 38→		if strings.Contains(strings.ToLower(combined), p) {
 39→			return true
 40→		}
 41→	}
 42→	return false
 43→}
