 61→func (k *Kiro) RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error) {
 62→	cfg := &runConfig{}
 63→	for _, o := range opts {
 64→		o(cfg)
 65→	}
 66→
 67→	// kiro-cli --no-interactive mode does not fire agent hooks, so we must
 68→	// use interactive (tmux) mode and send the prompt through the TUI.
 69→	timeout := 2 * time.Minute
 70→	if cfg.PromptTimeout > 0 {
 71→		timeout = cfg.PromptTimeout
 72→	}
 73→
 74→	// --agent entire activates the agent profile that contains our hooks
 75→	args := []string{"chat", "-a", "--agent", "entire"}
 76→	if cfg.Model != "" {
 77→		args = append(args, "--model", cfg.Model)
 78→	}
 79→
 80→	name := fmt.Sprintf("kiro-run-%d", time.Now().UnixNano())
 81→	s, err := NewTmuxSession(name, dir, nil, k.Binary(), args...)
 82→	if err != nil {
 83→		return Output{}, fmt.Errorf("starting kiro session: %w", err)
 84→	}
 85→	defer func() { _ = s.Close() }()
 86→
 87→	// Wait for initial prompt — kiro-cli TUI shows "!>" in trust-all mode
 88→	if _, err := s.WaitFor(k.PromptPattern(), 30*time.Second); err != nil {
 89→		content := s.Capture()
 90→		return Output{
 91→			Command: k.Binary() + " " + strings.Join(args, " "),
 92→			Stderr:  content,
 93→		}, fmt.Errorf("waiting for kiro startup: %w", err)
 94→	}
 95→	s.stableAtSend = ""
 96→
 97→	// Send the prompt
 98→	if err := s.Send(prompt); err != nil {
 99→		return Output{}, fmt.Errorf("sending prompt to kiro: %w", err)
100→	}
101→
102→	// Wait for "Credits:" which only appears after the agent finishes a response.
103→	// More reliable than PromptPattern for single-prompt mode since it uniquely
104→	// identifies response completion without needing to distinguish echoed input.
105→	content, err := s.WaitFor(`Credits:`, timeout)
106→	exitCode := 0
107→	if err != nil {
108→		exitCode = -1
109→	}
110→
111→	return Output{
112→		Command:  k.Binary() + " " + strings.Join(args, " ") + " " + fmt.Sprintf("%q", prompt),
113→		Stdout:   content,
114→		ExitCode: exitCode,
115→	}, err
116→}
